 * 波特率。要从 telnet 调用：改完以后串口那头得换波特率才能再说话，
 * 改回去也靠 telnet。
 */

static int diag_baud(long baud)
{
  struct termios t;
  int fd;
  int ret;

  if (baud != 115200 && baud != 1500000)
    {
      printf("只支持 115200 / 1500000\\n");
      return 1;
    }

  fd = open("/dev/ttyS0", O_RDWR | O_NOCTTY);
  if (fd < 0)
    {
      printf("打不开 /dev/ttyS0\\n");
      return 1;
    }

  ret = tcgetattr(fd, &t);
  if (ret == 0)
    {
      tcdrain(fd);
      cfsetspeed(&t, baud);
      ret = tcsetattr(fd, TCSANOW, &t);
    }

  if (ret == 0)
    {
      ret = tcgetattr(fd, &t);
    }

  close(fd);
  printf("ttyS0 波特率 -> %ld：%s（读回 %ld）\\n", baud,
         ret == 0 ? "成功" : "失败", (long)cfgetispeed(&t));
  return ret == 0 ? 0 : 1;
}

