static bool g_started;
static int8_t g_state[K7_HOME_MAX];
static struct k7_home_status_s g_st;
static time_t g_last_tx;

static time_t home_now(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return ts.tv_sec;
}

/* ---- 报文编码 ---- */

static size_t put_len(uint8_t *p, size_t len)
{
  size_t n = 0;

  do
    {
      uint8_t b = len & 0x7f;

      len >>= 7;
      p[n++] = len ? (b | 0x80) : b;
    }
  while (len);

  return n;
}

static size_t put_str(uint8_t *p, const char *s, size_t len)
{
  p[0] = len >> 8;
  p[1] = len & 0xff;
  memcpy(p + 2, s, len);
  return len + 2;
}

/* 固定头 + 已经排好的 body 拷进 out，返回总长；放不下返回 0 */

static size_t frame(uint8_t *out, size_t cap, uint8_t type,
                    const uint8_t *body, size_t len)
{
  uint8_t hdr[5];
  size_t h;

  hdr[0] = type;
  h = 1 + put_len(hdr + 1, len);
  if (h + len > cap)
    {
      return 0;
    }

  memcpy(out, hdr, h);
  memcpy(out + h, body, len);
  return h + len;
}

/* 持锁调用。整包要么全发出去，要么算失败（调用者断开重连）。 */

static int send_locked(const uint8_t *buf, size_t len)
{
  ssize_t ret;

  if (g_fd < 0)
    {
      return -ENOTCONN;
    }

  ret = send(g_fd, buf, len, MSG_DONTWAIT);
  if (ret < 0)
    {
      return -errno;
    }

  if ((size_t)ret != len)
    {
      return -EAGAIN;
    }

  g_last_tx = home_now();
  return 0;
}

static int publish_locked(const char *topic, const char *payload,
                          bool retain)
{
  uint8_t body[192];
  uint8_t pkt[200];
  size_t tl = strlen(topic);
  size_t pl = strlen(payload);
  size_t n;

  if (tl + pl + 2 > sizeof(body))
    {
      return -E2BIG;
    }

  n = put_str(body, topic, tl);
  memcpy(body + n, payload, pl);
  n = frame(pkt, sizeof(pkt), MQTT_PUBLISH | (retain ? 1 : 0), body,
            n + pl);
  return n ? send_locked(pkt, n) : -E2BIG;
}

/* ---- 连接 ---- */

static int tcp_connect(void)
{
  struct sockaddr_in sa;
  struct pollfd pfd;
  socklen_t sl = sizeof(int);
  int err = 0;
  int fd;

  memset(&sa, 0, sizeof(sa));
  sa.sin_family = AF_INET;
  sa.sin_port = htons(HOME_PORT);
  if (inet_pton(AF_INET, HOME_HOST, &sa.sin_addr) != 1)
    {
      return -EINVAL;
    }

  fd = socket(AF_INET, SOCK_STREAM, 0);
  if (fd < 0)
    {
      return -errno;
    }

  /* 非阻塞 connect + poll：broker 不在时不会卡在内核的 SYN 重传里 */

  fcntl(fd, F_SETFL, fcntl(fd, F_GETFL) | O_NONBLOCK);
  if (connect(fd, (struct sockaddr *)&sa, sizeof(sa)) < 0)
    {
      if (errno != EINPROGRESS)
        {
          err = -errno;
          goto fail;
        }

      pfd.fd = fd;
      pfd.events = POLLOUT;
      if (poll(&pfd, 1, HOME_CONNECT_MS) <= 0)
        {
          err = -ETIMEDOUT;
          goto fail;
        }

      if (getsockopt(fd, SOL_SOCKET, SO_ERROR, &err, &sl) < 0)
        {
          err = errno;
        }

      if (err)
        {
          err = -err;
          goto fail;
        }
    }

  return fd;

fail:
  close(fd);
  return err;
}

/* 收满 len 字节或超时 */

static int recv_exact(int fd, uint8_t *buf, size_t len, int timeout_ms)
{
  struct pollfd pfd;
  size_t got = 0;
  ssize_t ret;

  pfd.fd = fd;
  pfd.events = POLLIN;
  while (got < len)
    {
      if (poll(&pfd, 1, timeout_ms) <= 0)
        {
          return -ETIMEDOUT;
        }

      ret = recv(fd, buf + got, len - got, 0);
      if (ret <= 0)
        {
          return ret < 0 ? -errno : -ECONNRESET;
        }

      got += ret;
    }

  return 0;
}

static int mqtt_handshake(int fd)
{
  static const char will[] = "offline";
  uint8_t body[128];
  uint8_t pkt[136];
  uint8_t ack[4];
  size_t n = 0;
  size_t len;
  int ret;

  n += put_str(body + n, "MQTT", 4);
  body[n++] = 4;                         /* 3.1.1 */
  body[n++] = 0x02 | 0x04 | 0x20;        /* clean session, 遗嘱, 遗嘱 retain */
  body[n++] = HOME_KEEPALIVE_S >> 8;
  body[n++] = HOME_KEEPALIVE_S & 0xff;
  n += put_str(body + n, HOME_CLIENT_ID, strlen(HOME_CLIENT_ID));
  n += put_str(body + n, HOME_SELF_TOPIC, strlen(HOME_SELF_TOPIC));
  n += put_str(body + n, will, strlen(will));

  len = frame(pkt, sizeof(pkt), MQTT_CONNECT, body, n);
  if (send(fd, pkt, len, 0) != (ssize_t)len)
    {
      return -EIO;
    }

  ret = recv_exact(fd, ack, 4, HOME_CONNECT_MS);
  if (ret < 0)
    {
      return ret;
    }

  if (ack[0] != MQTT_CONNACK || ack[1] != 2)
    {
      return -EPROTO;
    }

  if (ack[3] != 0)
    {
      syslog(LOG_WARNING, "家居: broker 拒绝连接，返回码 %u\n", ack[3]);
      return -ECONNREFUSED;
    }

  /* 订阅 home/+/state。SUBACK 交给收包循环，不在这里等。 */

  n = 0;
  body[n++] = 0;
  body[n++] = 1;                         /* packet id */
  n += put_str(body + n, HOME_PREFIX "+/state",
               strlen(HOME_PREFIX "+/state"));
  body[n++] = 0;                         /* QoS 0 */
  len = frame(pkt, sizeof(pkt), MQTT_SUBSCRIBE, body, n);
  if (send(fd, pkt, len, 0) != (ssize_t)len)
    {
      return -EIO;
    }

  return 0;
}

/* ---- 收包 ---- */

static void on_publish(const uint8_t *p, size_t len, uint8_t flags)
{
  const char *topic;
  const char *payload;
  size_t tl;
  size_t pl;
  size_t pre = strlen(HOME_PREFIX);
  int v;
  int i;

  if (len < 2)
    {
      return;
    }

  tl = (p[0] << 8) | p[1];
  if (2 + tl > len)
    {
      return;
    }

  topic = (const char *)p + 2;
  payload = topic + tl;
  pl = len - 2 - tl;
  if ((flags >> 1) & 3)
    {
      /* QoS 1/2 带两字节 packet id。订阅时要的是 QoS 0，按理不会来 */

      if (pl < 2)
        {
          return;
        }

      payload += 2;
      pl -= 2;
    }

  /* home/<id>/state */

  if (tl <= pre + 6 || memcmp(topic, HOME_PREFIX, pre) != 0 ||
      memcmp(topic + tl - 6, "/state", 6) != 0)
    {
      return;
    }

  if ((pl == 2 && strncasecmp(payload, "ON", 2) == 0) ||
      (pl == 1 && payload[0] == '1'))
    {
      v = 1;
    }
  else if ((pl == 3 && strncasecmp(payload, "OFF", 3) == 0) ||
           (pl == 1 && payload[0] == '0'))
    {
      v = 0;
    }
  else
    {
      return;
    }

  for (i = 0; i < g_n; i++)
    {
      size_t il = strlen(g_ids[i]);

      if (il == tl - pre - 6 && memcmp(topic + pre, g_ids[i], il) == 0)
        {
          pthread_mutex_lock(&g_lock);
          if (g_state[i] != v)
            {
              g_state[i] = v;
              g_st.gen++;
            }

          pthread_mutex_unlock(&g_lock);
          return;
        }
    }
}

/* 从 buf 里拆出完整报文逐个处理，返回消耗掉的字节数；格式错 / 太大返回 -1 */

static ssize_t parse(const uint8_t *buf, size_t len)
{
  size_t off = 0;

  while (len - off >= 2)
    {
      size_t rl = 0;
      size_t h = 1;
      int shift = 0;

      for (; ; )
        {
          if (off + h >= len)
            {
              return off;                /* 长度字段还没收全 */
            }

          rl |= (size_t)(buf[off + h] & 0x7f) << shift;
          if (!(buf[off + h++] & 0x80))
            {
              break;
            }

          shift += 7;
          if (h > 4)
            {
              return -1;
            }
        }

      if (h + rl > HOME_RX_CAP)
        {
          return -1;
        }

      if (off + h + rl > len)
        {
          return off;
        }

      if ((buf[off] & 0xf0) == MQTT_PUBLISH)
        {
          on_publish(buf + off + h, rl, buf[off] & 0x0f);
        }

      /* SUBACK / PINGRESP 只用来证明连接活着，不用解析 */

      off += h + rl;
    }

  return off;
}

static int session(int fd)
{
  static uint8_t rx[HOME_RX_CAP];
  static const uint8_t ping[2] =
  {
    MQTT_PINGREQ, 0
  };

  struct pollfd pfd;
  size_t len = 0;
  time_t last_rx = home_now();
  ssize_t ret;

  pfd.fd = fd;
  pfd.events = POLLIN;

  for (; ; )
    {
      time_t now = home_now();

      if (now - last_rx > HOME_DEAD_S)
        {
          return -ETIMEDOUT;
        }

      pthread_mutex_lock(&g_lock);
      ret = 0;
      if (now - g_last_tx >= HOME_PING_S)
        {
          ret = send_locked(ping, sizeof(ping));
        }

      pthread_mutex_unlock(&g_lock);
      if (ret < 0)
        {
          return ret;
        }

      if (poll(&pfd, 1, 1000) <= 0)
        {
          continue;
        }

      ret = recv(fd, rx + len, sizeof(rx) - len, MSG_DONTWAIT);
      if (ret == 0)
        {
          return -ECONNRESET;
        }

      if (ret < 0)
        {
          if (errno == EAGAIN || errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      last_rx = home_now();
      len += ret;
      ret = parse(rx, len);
      if (ret < 0)
        {
          return -EPROTO;
        }

      len -= ret;
      memmove(rx, rx + ret, len);
    }
}

static void set_connected(int fd, int err)
{
  int i;

  pthread_mutex_lock(&g_lock);
  g_fd = fd;
  g_st.connected = fd >= 0;
  if (err)
    {
      g_st.err = err;
    }

  /* 断开后状态就不可信了：设备可能在这期间被别处开关过 */

  if (fd < 0)
    {
      for (i = 0; i < g_n; i++)
        {
          g_state[i] = -1;
        }
    }
  else
    {
      g_last_tx = home_now();
      publish_locked(HOME_SELF_TOPIC, "online", true);
    }

  g_st.gen++;
  pthread_mutex_unlock(&g_lock);
}

static void *home_thread(void *arg)
{
  int backoff = 1;
  int logged = 0;

  (void)arg;

  for (; ; )
    {
      int fd = tcp_connect();
      int ret;

      if (fd >= 0)
        {
          ret = mqtt_handshake(fd);
          if (ret == 0)
            {
              syslog(LOG_INFO, "家居: 已连上 broker %s\n", g_st.broker);
              set_connected(fd, 0);
              backoff = 1;
              logged = 0;
              ret = session(fd);
              set_connected(-1, -ret);
              syslog(LOG_WARNING, "家居: 与 broker 断开 (%d)\n", ret);
            }

          close(fd);
        }
      else
        {
          ret = fd;
        }

      if (ret < 0)
        {
          pthread_mutex_lock(&g_lock);
          g_st.err = -ret;
          g_st.gen++;
          pthread_mutex_unlock(&g_lock);

          /* 连不上时只记前几次，免得 broker 不在时日志刷屏 */

          if (logged++ < 3)
            {
              syslog(LOG_INFO, "家居: 连不上 %s (%d)，%d 秒后重试\n",
                     g_st.broker, ret, backoff);
            }
        }

      sleep(backoff);
      backoff = backoff * 2 > HOME_BACKOFF_MAX ? HOME_BACKOFF_MAX
                                               : backoff * 2;
    }

  return NULL;
}

/* ---- 对界面的接口 ---- */

int k7_home_start(const char *const *ids, int n)
{
  pthread_attr_t attr;
  pthread_t tid;
  int ret;
  int i;

  if (g_started)
    {
      return 0;
    }

  g_ids = ids;
  g_n = n > K7_HOME_MAX ? K7_HOME_MAX : n;
  for (i = 0; i < K7_HOME_MAX; i++)
    {
      g_state[i] = -1;
    }

  snprintf(g_st.broker, sizeof(g_st.broker), "%s:%d", HOME_HOST,
           HOME_PORT);
  if (HOME_HOST[0] == '\0')
    {
      g_st.err = ENOSYS;                 /* 没配置 broker */
      return -ENOSYS;
    }

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 8192);
  ret = pthread_create(&tid, &attr, home_thread, NULL);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      g_st.err = ret;
      return -ret;
    }

  pthread_setname_np(tid, "k7home");
  pthread_detach(tid);
  g_started = true;
  return 0;
}

void k7_home_status(struct k7_home_status_s *st)
{
  pthread_mutex_lock(&g_lock);
  *st = g_st;
  pthread_mutex_unlock(&g_lock);
}

int k7_home_state(int i)
{
  int v;

  if (i < 0 || i >= g_n)
    {
      return -1;
    }

  pthread_mutex_lock(&g_lock);
  v = g_state[i];
  pthread_mutex_unlock(&g_lock);
  return v;
}

int k7_home_set(int i, bool on)
{
  char topic[64];
  int ret;

  if (i < 0 || i >= g_n)
    {
      return -EINVAL;
    }

  snprintf(topic, sizeof(topic), HOME_PREFIX "%s/set", g_ids[i]);
  pthread_mutex_lock(&g_lock);
  ret = publish_locked(topic, on ? "ON" : "OFF", false);
  pthread_mutex_unlock(&g_lock);
  return ret;
}

int k7_home_scene(const char *name)
{
  int ret;

  pthread_mutex_lock(&g_lock);
  ret = publish_locked(HOME_PREFIX "scene/set", name, false);
  pthread_mutex_unlock(&g_lock);
  return ret;
}

#!/usr/bin/env bash
# 在电脑上假扮几台家居设备，给 K7 家居页联调用（主题约定见
# app/kickpi_ui/k7_home.h）。没有真实设备、也没有 Home Assistant 时用它。
#
#   bash scripts/home-sim.sh [broker 地址，默认 localhost]
#
# 收到 home/<id>/set 就把同样的值以 retain 发回 home/<id>/state，像一台
# 听话的设备；收到 home/scene/set 就按场景改几台设备的状态。
# 想测"设备没响应"：SIM_DEAD=tv bash scripts/home-sim.sh，电视就不回报。
# 依赖：mosquitto-clients（apt install mosquitto-clients）。
set -euo pipefail

HOST=${1:-localhost}
DEAD=${SIM_DEAD:-}
DEVICES="living_light desk_lamp ac fresh_air kettle tv"

state() { mosquitto_pub -h "$HOST" -r -t "home/$1/state" -m "$2"; }

scene() {
  case $1 in
    home)  state living_light ON;  state ac ON;  state fresh_air ON ;;
    away)  for d in $DEVICES; do state "$d" OFF; done ;;
    focus) state desk_lamp ON; state living_light OFF; state tv OFF ;;
    rest)  state living_light OFF; state desk_lamp OFF; state tv OFF ;;
    *)     echo "未知场景 $1" >&2 ;;
  esac
}

# 初始状态：都关着，客厅灯开着
for d in $DEVICES; do state "$d" OFF; done
state living_light ON
echo "模拟设备已就绪（broker $HOST）：$DEVICES"

mosquitto_sub -h "$HOST" -v -t 'home/+/set' | while read -r topic payload; do
  id=${topic#home/}; id=${id%/set}
  echo "$(date +%T) $topic $payload"
  if [[ $id == scene ]]; then
    scene "$payload"
  elif [[ " $DEVICES " == *" $id "* && " $DEAD " != *" $id "* ]]; then
    state "$id" "$payload"
  fi
done
{
  bool note = g_home_note_until > now_us();
  uint32_t dot;
  int i;

  for (i = 0; i < HOME_N; i++)
    {
      int v = k7_home_state(i);
      bool on = v == 1;
      const char *word;

      if (!st->connected)
        {
          word = "离线";
        }
      else if (g_home_want[i] >= 0)
        {
          word = g_home_want[i] ? "正在打开…" : "正在关闭…";
        }
      else if (v < 0)
        {
          word = "未知";
        }
      else
        {
          word = on ? "开着" : "关着";
        }

      lv_obj_set_style_bg_color(g_home_tile[i],
                                lv_color_hex(on ? g_home_dev[i].color
                                                : UI_CARD), 0);
      lv_obj_set_style_text_color(g_home_icon[i],
                                  lv_color_hex(on ? UI_ON_COLOR
                                                  : g_home_dev[i].color), 0);
      lv_obj_set_style_text_color(g_home_name[i],
                                  lv_color_hex(on ? UI_ON_COLOR : UI_TEXT),
                                  0);
      lv_obj_set_style_text_color(g_home_word[i],
                                  lv_color_hex(on ? UI_ON_COLOR : UI_DIM),
                                  0);
      lv_label_set_text(g_home_word[i], word);
      lv_obj_set_style_opa(g_home_tile[i],
                           st->connected ? LV_OPA_COVER : LV_OPA_50, 0);
      lv_obj_update_flag(g_home_tile[i], LV_OBJ_FLAG_CLICKABLE, st->connected);
    }

  for (i = 0; i < 4; i++)
    {
      lv_obj_set_style_opa(g_home_scene[i],
                           st->connected ? LV_OPA_COVER : LV_OPA_50, 0);
      lv_obj_update_flag(g_home_scene[i], LV_OBJ_FLAG_CLICKABLE,
                      st->connected);
    }

  if (note)
    {
      dot = UI_SIT_OVER;
      lv_label_set_text(g_home_link, g_home_note);
    }
  else if (st->connected)
    {
      dot = UI_OK;
      lv_label_set_text_fmt(g_home_link, "已连接  ·  %s", st->broker);
    }
  else if (st->err == ENOSYS)
    {
      dot = UI_DIM;
      lv_label_set_text(g_home_link, "未配置家庭网关");
    }
  else
    {
      dot = UI_BAD;
      lv_label_set_text_fmt(g_home_link, "离线  ·  正在重连 %s",
                            st->broker);
    }

  lv_obj_set_style_bg_color(g_home_dot, lv_color_hex(dot), 0);
}

static void home_poll(void)
{
  struct k7_home_status_s st;
  uint64_t now;
  int i;

  if (g_home_link == NULL)
    {
      return;
    }

  k7_home_status(&st);
  now = now_us();
  for (i = 0; i < HOME_N; i++)
    {
      if (g_home_want[i] < 0)
        {
          continue;
        }

      if (!st.connected || k7_home_state(i) == g_home_want[i])
        {
          g_home_want[i] = -1;
          g_home_dirty = true;
        }
      else if (now >= g_home_deadline[i])
        {
          g_home_want[i] = -1;
          home_note("%s没有响应", g_home_dev[i].name);
        }
    }

  if (g_home_note_until != 0 && now >= g_home_note_until)
    {
      g_home_note_until = 0;
      g_home_dirty = true;
    }

  if (st.gen != g_home_gen || g_home_dirty)
    {
      g_home_gen = st.gen;
      g_home_dirty = false;
      home_paint(&st);
    }
}

static void home_tile_cb(lv_event_t *e)
{
  int i = (int)(intptr_t)lv_event_get_user_data(e);
  bool on;

  if (g_home_want[i] >= 0)
    {
      return;                            /* 上一次还在等回报 */
    }

  on = k7_home_state(i) != 1;
  if (k7_home_set(i, on) < 0)
    {
      home_note("%s：指令没发出去", g_home_dev[i].name);
      return;
    }

  g_home_want[i] = on;
  g_home_deadline[i] = now_us() + HOME_WAIT_US;
  g_home_dirty = true;
}

static void home_scene_cb(lv_event_t *e)
{
  int i = (int)(intptr_t)lv_event_get_user_data(e);

  home_note(k7_home_scene(g_home_scenes[i][0]) < 0 ? "%s：指令没发出去"
                                                   : "已发出场景：%s",
            g_home_scenes[i][2]);
}

static lv_obj_t *home_tile(lv_obj_t *parent, int32_t w, int32_t h,
                           lv_event_cb_t cb, int i)
{
  lv_obj_t *tile = lv_obj_create(parent);

  lv_obj_set_size(tile, w, h);
  lv_obj_set_style_bg_color(tile, lv_color_hex(UI_CARD), 0);
  lv_obj_set_style_bg_opa(tile, LV_OPA_80, LV_STATE_PRESSED);
  lv_obj_set_style_border_width(tile, 0, 0);
  lv_obj_set_style_radius(tile, 28, 0);
  lv_obj_set_style_pad_all(tile, 24, 0);
  lv_obj_remove_flag(tile, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_add_event_cb(tile, cb, LV_EVENT_CLICKED, (void *)(intptr_t)i);
  return tile;
}

static void home_build(lv_obj_t *tab)
{
  lv_obj_t *row;
  lv_obj_t *grid;
  lv_obj_t *lbl;
