  /* echo 1 / 0 > /tmp/k7-studio：开始 / 结束录制（调试入口） */

  fp = fopen("/tmp/k7-studio", "r");
  if (fp != NULL)
    {
      int on = 0;

      if (fscanf(fp, "%d", &on) == 1)
        {
          k7_studio_status(&st);
          if ((on != 0) != st.onair)
            {
              work_toggle();
            }
        }

      fclose(fp);
      unlink("/tmp/k7-studio");
    }

  k7_studio_status(&st);
  if (st.gen != g_work_gen || st.elapsed_s != g_work_secs)
    {
      work_paint();
    }
}

