/* UTF-8 安全的拷贝：截断时退到字符边界，不留半个汉字 */

static void utf8_copy(char *dst, size_t size, const char *src)
{
  size_t len = strlen(src);

  if (len >= size)
    {
      len = size - 1;
      while (len > 0 && ((unsigned char)src[len] & 0xc0) == 0x80)
        {
          len--;
        }
    }

  memcpy(dst, src, len);
  dst[len] = '\0';
}

