        }

      if (ret < 0)
        {
          printf("第 %d 次推理失败：%d\n", k, ret);
          goto out;
        }

      printf("第 %d 次：rknn_run %ld ms", k, ms_since(&t0));
      if (rknn_query(ctx, RKNN_QUERY_PERF_RUN, &perf, sizeof(perf)) == 0)
