    if (bufs[i].p == MAP_FAILED) {
      bufs[i].p = NULL;
      printf("mmap 缓冲 %d 失败: %s\n", i, strerror(errno));
      goto out;
    }
    printf("缓冲 %d: %p + %zu\n", i, bufs[i].p, bufs[i].len);
    if (ioctl(fd, VIDIOC_QBUF, &b) < 0) {
      printf("QBUF %d 失败: %s\n", i, strerror(errno));
      goto out;
    }
