  h = fmt.fmt.pix_mp.height;
  bpl = fmt.fmt.pix_mp.plane_fmt[0].bytesperline;
  printf("ISP %s: %ux%u fourcc=%.4s planes=%u bytesperline=%u sizeimage=%u\n",
