XCamReturn AiqCamHw_start(AiqCamHwBase_t* pCamHw) {
    XCamReturn ret          = XCAM_RETURN_NO_ERROR;
    AiqSensorHw_t* sensorHw = NULL;
    AiqLensHw_t* lensHw     = NULL;

