#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>

int main(int argc, char **argv)
{
  int fd = open("/dev/i2c-1", O_RDWR);
  unsigned reg = argc > 1 ? strtoul(argv[1], NULL, 0) : 0;
  unsigned n = argc > 2 ? strtoul(argv[2], NULL, 0) : 1, i;
  uint8_t r, v[64];

  if (fd < 0 || n < 1 || n > 64) { perror("open/args"); return 1; }
  r = reg;
  struct i2c_msg m[2] = {
