    { .addr = 0x23, .flags = I2C_M_RD, .len = n, .buf = v },
  };
  struct i2c_rdwr_ioctl_data x = { .msgs = m, .nmsgs = 2 };
  if (ioctl(fd, I2C_RDWR, &x) != 2) { perror("I2C_RDWR"); return 1; }
  for (i = 0; i < n; i++)
    printf("0x%02x = 0x%02x\n", reg + i, v[i]);
  return 0;
}
